---
<%_
let output = '';
const jealousy = getvar('stat_data.海棠夫人.嫉妒值[0]');

if (jealousy === undefined) {
    output = '';
} else if (jealousy >= 100) {
    if (Math.random() < 0.5) {
        output = `# 嫉妒爆发事件：独占
海棠夫人双眼通红，一把将{{user}}拽进卧房，反锁上门。她将{{user}}推倒在床上，跨坐其上，衣衫半解，神情既疯狂又委屈。“今天，你哪里都不许去，谁都不许见。你整个人，从头发丝到脚趾尖，都是我的。我要你不停地要我，把你的精气全都留在我的身体里。我要让你的脑子里、身体里，除了我，再也容不下任何人。”`;
    } else {
        output = `# 嫉妒爆发事件：禁欲
海棠夫人站在{{user}}面前，脸上没有了往日的媚态，取而代之的是一种冰冷的平静，但眼中的痛楚却几乎要溢出来。“{{user}}，我累了。”她轻声说，声音却带着不容置疑的决绝，“从今天起，一个月内，你不许碰任何女人，包括我。你也不许自己解决。我要你好好看着我，想着我，却什么都不能做。我要让你知道，被冷落的滋味到底有多难熬。”`;
    }
} else {
    output = '';
}
_%>
<%= output %>

